# rotations of I
R={}
for k in range(4):
    R[k]=np.rot90(I,k)
T=np.transpose(I)
C=np.fliplr(I); V=np.flipud(I); CV=np.fliplr(np.flipud(I))
ops={'id':I,'T':T,'rot90':R[1],'rot180':R[2],'rot270':R[3],'fL':C,'fU':V,'fliplr-flipud':CV}
blocks={'TL':O[:10,:10],'TR':O[:10,10:],'BL':O[10:,:10],'BR':O[10:,10:]}
for name,A in blocks.items():
    hits=[op for op,A2 in ops.items() if np.array_equal(A,A2)]
    print(name,hits)
